        Wire.writeSlicePermission(w, v.permissions)
        w.data(v.value)
        w.bool(v.dynamic)
    }

    fun readServedCharacteristic(r: AsukaNativeReader): ServedCharacteristic {
        val f0 = r.string()
        val f1 = Wire.readSliceProperty(r)
        val f2 = Wire.readSlicePermission(r)
        val f3 = r.data()
        val f4 = r.bool()
        return ServedCharacteristic(uuid = f0, properties = f1, permissions = f2, value = f3, dynamic = f4)
    }

    fun writeSliceFoundCharacteristic(w: AsukaNativeWriter, v: List<FoundCharacteristic>) {
        w.len(v.size)
        for (e in v) Wire.writeFoundCharacteristic(w, e)
    }

    fun readSliceFoundCharacteristic(r: AsukaNativeReader): List<FoundCharacteristic> {
        val n = r.len()
        return List(n) { Wire.readFoundCharacteristic(r) }
    }

    fun writeSliceServedCharacteristic(w: AsukaNativeWriter, v: List<ServedCharacteristic>) {
        w.len(v.size)
        for (e in v) Wire.writeServedCharacteristic(w, e)
    }

    fun readSliceServedCharacteristic(r: AsukaNativeReader): List<ServedCharacteristic> {
        val n = r.len()
        return List(n) { Wire.readServedCharacteristic(r) }
    }

    fun writeSlicePermission(w: AsukaNativeWriter, v: List<Permission>) {
        w.len(v.size)
        for (e in v) w.int(e.value)
    }

    fun readSlicePermission(r: AsukaNativeReader): List<Permission> {
        val n = r.len()
        return List(n) { Permission(r.int()) }
    }

    fun writeSliceProperty(w: AsukaNativeWriter, v: List<Property>) {
        w.len(v.size)
        for (e in v) w.int(e.value)
    }

    fun readSliceProperty(r: AsukaNativeReader): List<Property> {
        val n = r.len()
        return List(n) { Property(r.int()) }
    }

}
